 static void Configure(Material m,Texture2D texture){m.shader=Shader.Find("Universal Render Pipeline/Lit");m.SetTexture("_BaseMap",texture);m.SetTexture("_MainTex",texture);m.SetColor("_BaseColor",Color.white);m.SetColor("_Color",Color.white);m.SetFloat("_Surface",0);m.SetFloat("_AlphaClip",1);m.SetFloat("_Cutoff",.42f);m.SetFloat("_Cull",2);m.SetFloat("_AlphaToMask",1);m.SetFloat("_Smoothness",.08f);m.SetFloat("_Metallic",0);m.SetFloat("_SpecularHighlights",0);m.SetFloat("_EnvironmentReflections",0);m.SetTexture("_BumpMap",null);m.SetTexture("_OcclusionMap",null);m.SetTexture("_MetallicGlossMap",null);m.SetTexture("_EmissionMap",null);m.SetColor("_EmissionColor",Color.black);foreach(string k in new[]{"_ALPHATEST_ON","_SPECULARHIGHLIGHTS_OFF","_ENVIRONMENTREFLECTIONS_OFF"})m.EnableKeyword(k);foreach(string k in new[]{"_SURFACE_TYPE_TRANSPARENT","_ALPHAPREMULTIPLY_ON","_NORMALMAP","_EMISSION","_METALLICSPECGLOSSMAP"})m.DisableKeyword(k);m.SetOverrideTag("RenderType","TransparentCutout");m.renderQueue=2450;m.doubleSidedGI=true;m.enableInstancing=true;EditorUtility.SetDirty(m);}
 static Mesh MeshFor(string composer,string kind,int variant,string quality)=>AssetDatabase.LoadAllAssetsAtPath(Shared+"/Models/"+composer+"_"+kind+"_"+variant.ToString("00")+"_"+quality+".fbx").OfType<Mesh>().Single();
 static string Quality(Mesh mesh){string name=Path.GetFileNameWithoutExtension(AssetDatabase.GetAssetPath(mesh));return Q.Single(q=>name.EndsWith("_"+q,StringComparison.Ordinal));}
 static bool IsVine(Mesh m){if(!m)return false;string path=AssetDatabase.GetAssetPath(m);return path.StartsWith(Prop+"/")||path.StartsWith(Shared+"/Models/")&&path.Contains("_Vine_");}
 static uint Hash(string value){uint h=2166136261;foreach(char c in value)h=unchecked((h^c)*16777619);return h;}
 static string NameKey(MeshFilter f){var outer=PrefabUtility.GetOutermostPrefabInstanceRoot(f.gameObject);string value=outer?outer.name:f.transform.parent.name;return Regex.Replace(value,@"_(Low|Mid|HighMid|High|Ultra)$","");}
 static void Mark(Renderer r){r.shadowCastingMode=ShadowCastingMode.TwoSided;r.receiveShadows=true;r.lightProbeUsage=LightProbeUsage.BlendProbes;if(r is MeshRenderer mr)mr.receiveGI=ReceiveGI.LightProbes;GameObjectUtility.SetStaticEditorFlags(r.gameObject,StaticEditorFlags.ContributeGI);if(PrefabUtility.IsPartOfPrefabInstance(r)){PrefabUtility.RecordPrefabInstancePropertyModifications(r);PrefabUtility.RecordPrefabInstancePropertyModifications(r.gameObject);}}
 public static void ApplyForCurrentScene(string composer=null){var scene=SceneManager.GetActiveScene();if(string.IsNullOrEmpty(composer))composer=scene.name.StartsWith("Monteverdi")?"Monteverdi":scene.name.StartsWith("Pachelbel")?"Pachelbel":"";if(composer!="Monteverdi"&&composer!="Pachelbel")return;var material=AssetDatabase.LoadAssetAtPath<Material>(Shared+"/ReferenceFlora_Lit.mat");if(!material)return;foreach(var root in scene.GetRootGameObjects())Decorate(root,composer,material,scene.name);}
 static (int vines,int bouquets) Decorate(GameObject root,string composer,Material material,string layout){var original=root.GetComponentsInChildren<Transform>(true).Where(t=>!t.name.StartsWith("ReferenceFlora_Bouquet")).ToDictionary(t=>t,t=>(t.localPosition,t.localRotation,t.localScale));
 foreach(var t in root.GetComponentsInChildren<Transform>(true).Where(t=>t.name.StartsWith("ReferenceFlora_Bouquet")).ToArray())if(t)Object.DestroyImmediate(t.gameObject);
 var filters=root.GetComponentsInChildren<MeshFilter>(true);var vines=filters.Where(f=>IsVine(f.sharedMesh)).OrderBy(NameKey).ThenBy(f=>f.name).ToArray();int layoutSeed=layout.Contains("_02")?1:layout.Contains("_03")?3:0;
 var keys=vines.Select(NameKey).Distinct().OrderBy(k=>k).ToArray();for(int i=0;i<vines.Length;i++){var f=vines[i];string quality=Quality(f.sharedMesh);int variant=(Array.IndexOf(keys,NameKey(f))*5+layoutSeed)%6;f.sharedMesh=MeshFor(composer,"Vine",variant,quality);f.GetComponent<Renderer>().sharedMaterial=material;Mark(f.GetComponent<Renderer>());PrefabUtility.RecordPrefabInstancePropertyModifications(f);}
 int bouquets=0;foreach(var f in filters){if(!f.sharedMesh)continue;string path=AssetDatabase.GetAssetPath(f.sharedMesh);bool target=composer=="Monteverdi"?path.Contains("monteverdi_scenario_antique_bronze_urn"):false;if(!target)continue;var renderer=f.GetComponent<Renderer>();var bounds=renderer.bounds;string q=Quality(f.sharedMesh);int variant=(int)(Hash(NameKey(f))%4);var mesh=MeshFor(composer,"Bouquet",variant,q);var obj=new GameObject("ReferenceFlora_Bouquet_"+variant);obj.AddComponent<MeshFilter>().sharedMesh=mesh;var mr=obj.AddComponent<MeshRenderer>();mr.sharedMaterial=material;float scale=(composer=="Pachelbel"?Mathf.Clamp(bounds.size.x*2f,1.3f,2.6f):Mathf.Clamp(bounds.size.x*1.25f,.65f,1.25f))/Mathf.Max(mesh.bounds.size.x,.01f);obj.transform.position=new Vector3(bounds.center.x,bounds.max.y-.035f,bounds.center.z);obj.transform.rotation=Quaternion.Euler(0,Hash(NameKey(f))%360,0);obj.transform.localScale=Vector3.one*scale;obj.transform.SetParent(f.transform,true);Mark(mr);bouquets++;}
 foreach(var item in original){if(!item.Key)continue;if((item.Key.localPosition-item.Value.Item1).sqrMagnitude>1e-10f||Quaternion.Angle(item.Key.localRotation,item.Value.Item2)>.001f||(item.Key.localScale-item.Value.Item3).sqrMagnitude>1e-10f)throw new Exception("Existing transform changed: "+item.Key.name);}
 return(vines.Length,bouquets);}
 static void UpgradeScenes(){int sceneCount=0,vines=0,bouquets=0;foreach(string composer in new[]{"Monteverdi","Pachelbel"}){string folder="Assets/_Project/Art/Arenas/"+composer+"/Scenes";foreach(string path in Directory.EnumerateFiles(folder,"*.unity").OrderBy(p=>p)){Backup(path);var scene=EditorSceneManager.OpenScene(path,OpenSceneMode.Single);foreach(var root in scene.GetRootGameObjects()){var counts=Decorate(root,composer,flora,scene.name);vines+=counts.vines;bouquets+=counts.bouquets;}EditorSceneManager.SaveScene(scene);sceneCount++;log.Add(scene.name+" | shared flora and six continuous construction variants applied");}
