 static void MakeBakeCheck(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);QualitySettings.renderPipeline=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/_Project/Art/Arenas/Monteverdi/LightingPilot/Profiles/Mid_Recommended.asset");QualitySettings.vSyncCount=0;RenderSettings.skybox=null;RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.18f,.18f,.18f);RenderSettings.fog=false;
 var vertices=new List<Vector3>();var uv=new List<Vector2>();var uv2=new List<Vector2>();var triangles=new List<int>();var atlas=JsonUtility.FromJson<AtlasData>(File.ReadAllText(Work+"/atlas_regions.json"));for(int i=0;i<10;i++){float x=(i%5-2)*.57f,y=.7f+(i/5)*.75f;int start=vertices.Count;vertices.AddRange(new[]{new Vector3(x-.23f,y,0),new Vector3(x+.23f,y,0),new Vector3(x+.23f,y+.46f,0),new Vector3(x-.23f,y+.46f,0)});var r=atlas.regions[i].rect;uv.AddRange(new[]{new Vector2(r[0]/2048,1-r[3]/1536),new Vector2(r[2]/2048,1-r[3]/1536),new Vector2(r[2]/2048,1-r[1]/1536),new Vector2(r[0]/2048,1-r[1]/1536)});float a=i/10f+.006f,b=(i+1)/10f-.006f;uv2.AddRange(new[]{new Vector2(a,.02f),new Vector2(b,.02f),new Vector2(b,.98f),new Vector2(a,.98f)});triangles.AddRange(new[]{start,start+2,start+1,start,start+3,start+2});}
 var mesh=new Mesh{name="FloraAlphaCheck"};mesh.SetVertices(vertices);mesh.SetUVs(0,uv);mesh.SetUVs(1,uv2);mesh.SetTriangles(triangles,0);mesh.RecalculateNormals();string meshPath=Shared+"/FloraAlphaCheck.asset";var previous=AssetDatabase.LoadAssetAtPath<Mesh>(meshPath);if(previous){EditorUtility.CopySerialized(mesh,previous);Object.DestroyImmediate(mesh);mesh=previous;}else AssetDatabase.CreateAsset(mesh,meshPath);var card=new GameObject("LeavesAndFlowers_ReceiveAndCastBakedLight");card.AddComponent<MeshFilter>().sharedMesh=mesh;card.AddComponent<MeshRenderer>().sharedMaterial=flora;GameObjectUtility.SetStaticEditorFlags(card,StaticEditorFlags.ContributeGI);card.GetComponent<MeshRenderer>().receiveGI=ReceiveGI.Lightmaps;
 var grey=new Material(Shader.Find("Universal Render Pipeline/Lit"));grey.SetColor("_BaseColor",new Color(.65f,.65f,.65f));grey.SetFloat("_Smoothness",.05f);string greyPath=Shared+"/FloraCheckGrey.mat";var existing=AssetDatabase.LoadAssetAtPath<Material>(greyPath);if(existing){EditorUtility.CopySerialized(grey,existing);Object.DestroyImmediate(grey);grey=existing;}else AssetDatabase.CreateAsset(grey,greyPath);var floor=GameObject.CreatePrimitive(PrimitiveType.Plane);floor.name="BakedShadowReceiver";floor.transform.localScale=Vector3.one*.65f;floor.GetComponent<Renderer>().sharedMaterial=grey;GameObjectUtility.SetStaticEditorFlags(floor,StaticEditorFlags.ContributeGI);
 var sun=new GameObject("BakedSun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=2;sun.transform.rotation=Quaternion.Euler(48,-22,0);sun.shadows=LightShadows.Soft;sun.lightmapBakeType=LightmapBakeType.Baked;RenderSettings.sun=sun;var settings=new LightingSettings{name="ReferenceFloraAlphaCheck",bakedGI=true,realtimeGI=false,lightmapper=LightingSettings.Lightmapper.ProgressiveGPU,lightmapResolution=48,lightmapMaxSize=1024,directionalityMode=LightmapsMode.NonDirectional,directSampleCount=64,indirectSampleCount=64,environmentSampleCount=32,maxBounces=2};string sp=Shared+"/FloraAlphaCheckSettings.asset";var prior=AssetDatabase.LoadAssetAtPath<LightingSettings>(sp);if(prior){EditorUtility.CopySerialized(settings,prior);Object.DestroyImmediate(settings);settings=prior;}else AssetDatabase.CreateAsset(settings,sp);Lightmapping.lightingSettings=settings;
 checkCamera=new GameObject("FloraCheckCamera").AddComponent<Camera>();checkCamera.transform.position=new Vector3(2.8f,3.2f,-5.4f);checkCamera.transform.LookAt(new Vector3(0,.9f,.1f));checkCamera.fieldOfView=42;checkCamera.clearFlags=CameraClearFlags.SolidColor;checkCamera.backgroundColor=new Color(.09f,.10f,.12f);checkCamera.GetUniversalAdditionalCameraData().renderPostProcessing=false;EditorSceneManager.SaveScene(SceneManager.GetActiveScene(),"Assets/_Project/Scenes/Debug/ReferenceFlora_AlphaBakeCheck.unity");AssetDatabase.SaveAssets();}
 static void BakeTick(){try{EditorApplication.QueuePlayerLoopUpdate();if(EditorApplication.timeSinceStartup-started>600)throw new Exception("Flora alpha bake timed out");if(!baked){if(EditorApplication.timeSinceStartup-started<3||Lightmapping.isRunning)return;if(LightmapSettings.lightmaps.Length==0)throw new Exception("Flora alpha bake is empty");EditorSceneManager.SaveScene(SceneManager.GetActiveScene());AssetDatabase.SaveAssets();log.Add("Alpha bake check passed, lightmaps="+LightmapSettings.lightmaps.Length+", realtime lights=0");baked=true;ready=EditorApplication.timeSinceStartup+8;return;}if(EditorApplication.timeSinceStartup<ready||ShaderUtil.anythingCompiling)return;Capture(checkCamera,Work+"/Flora_AlphaBakeCheck.png");EditorApplication.update-=BakeTick;QualitySettings.SetQualityLevel(oldQuality,true);QualitySettings.renderPipeline=oldPipeline;QualitySettings.vSyncCount=oldVsync;SaveLog();MonteverdiLightingLab.Start();File.WriteAllText(Work+"/ready.txt","ready");}catch(Exception e){Fail(e);}}
 static void Capture(Camera cam,string path){var rt=new RenderTexture(1600,1000,24,RenderTextureFormat.ARGB32){antiAliasing=4};rt.Create();cam.targetTexture=rt;for(int i=0;i<3;i++)cam.Render();var prev=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(rt.width,rt.height,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);tex.Apply();File.WriteAllBytes(path,tex.EncodeToPNG());RenderTexture.active=prev;cam.targetTexture=null;Object.DestroyImmediate(tex);rt.Release();Object.DestroyImmediate(rt);}
 public static void VerifyFromCommandLine(){int result=0;try{CleanupPachelbelPlanters();ArenaBundleValidation.Register();var settings=UnityEditor.AddressableAssets.AddressableAssetSettingsDefaultObject.Settings;var lines=new List<string>{"Editor play mode: "+settings.ActivePlayModeDataBuilder.GetType().Name};int count=0;foreach(string composer in new[]{"Monteverdi","Pachelbel"})foreach(string path in Directory.EnumerateFiles("Assets/_Project/Art/Arenas/"+composer+"/Scenes","*.unity")){var scene=EditorSceneManager.OpenScene(path,OpenSceneMode.Single);var renderers=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(f=>f.sharedMesh&&AssetDatabase.GetAssetPath(f.sharedMesh).StartsWith(Shared+"/Models/")).ToArray();if(renderers.Length<12)throw new Exception("Flora missing from "+path);var materials=renderers.Select(f=>f.GetComponent<Renderer>().sharedMaterial).Distinct().ToArray();if(materials.Length!=1||materials[0].shader.name!="Universal Render Pipeline/Lit"||materials[0].GetFloat("_Cull")!=2||!materials[0].IsKeywordEnabled("_ALPHATEST_ON"))throw new Exception("Flora material contract failed in "+path);int tier=Array.IndexOf(Q,QualityFromPath(path));foreach(var dep in AssetDatabase.GetDependencies(path,true).Where(d=>d.StartsWith(Shared+"/"))){var entry=settings.FindAssetEntry(AssetDatabase.AssetPathToGUID(dep));if(entry==null)throw new Exception("Unregistered shared flora dependency: "+dep);if(dep.EndsWith(".fbx")){var q=QualityFromPath(dep);if(Array.IndexOf(Q,q)>tier)throw new Exception("Higher flora quality leaked into "+path);if(!entry.labels.Contains("ArenaDependency_Flora_"+composer+"_"+q))throw new Exception("Flora quality grouping failed: "+dep);}}lines.Add(scene.name+" | flora renderers="+renderers.Length+" | shared material=1 | dependency tiers OK");count++;}lines.Add("PASS: "+count+" production scenes, standard cutout material, shared palette and composer/quality-specific content dependencies.");File.WriteAllLines(Work+"/packaging_verification.txt",lines);}catch(Exception e){result=1;File.WriteAllText(Work+"/verification_error.txt",e.ToString());Debug.LogException(e);}EditorApplication.Exit(result);}
 static void CleanupPachelbelPlanters(){int removed=0;string folder="Assets/_Project/Art/Arenas/Pachelbel";foreach(string path in Directory.EnumerateFiles(folder+"/Scenes","*.unity")){var scene=EditorSceneManager.OpenScene(path,OpenSceneMode.Single);foreach(var t in scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Where(t=>t.name.StartsWith("ReferenceFlora_Bouquet")).ToArray()){Object.DestroyImmediate(t.gameObject);removed++;}EditorSceneManager.SaveScene(scene);}foreach(string path in Directory.EnumerateFiles(folder,"Pachelbel_Arena_*.prefab",SearchOption.TopDirectoryOnly)){var root=PrefabUtility.LoadPrefabContents(path);try{foreach(var t in root.GetComponentsInChildren<Transform>(true).Where(t=>t.name.StartsWith("ReferenceFlora_Bouquet")).ToArray())Object.DestroyImmediate(t.gameObject);PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}}File.WriteAllText(Work+"/pachelbel_scope.txt","Pachelbel: continuous vine replacement retained; experimental planter overlays removed="+removed+". Monteverdi retains its new floral planters.");}
 static string QualityFromPath(string path){string name=Path.GetFileNameWithoutExtension(path);return Q.Single(q=>name.EndsWith("_"+q,StringComparison.Ordinal));}
